/* Hand-written learning content. Facts come from the DubboEwaste repo and the
   research notes Josh supplied; anything unverified is labelled as such.
   Link shapes: {t, u} external, {t, doc} repo doc id, {t, q} web search. */
const C = {};

C.pipeline = [
  ["Source", "Source equipment", "Prefer fleet refreshes from businesses, schools, MSPs and community organisations. Ten similar ex-business laptops are easier to serialise, wipe, test, repair and sell than ten random household devices."],
  ["Authority", "Prove authority and ownership", "Record who is handing the item over and on what basis (donation, sale, client-owned for service). Refuse suspicious or disputed provenance. If the NSW second-hand dealer regime applies, supplier ID and an ownership statement are required."],
  ["Record", "Assign an asset and serial record", "Every significant item gets an asset ID tied to its serial or IMEI before anything else happens. The 47-field pilot tracker starts here."],
  ["Safety", "Safety triage", "Screen for swollen, punctured, wet, fire-affected or hot batteries before power-on. Refuse loose lithium, CRTs and contaminated gear in Phase 0. Never charge a questionable battery."],
  ["Data", "Secure data sanitisation", "Follow a documented program aligned to NIST SP 800-88 Rev. 2 and the ASD ISM media guidelines. Log method, tool and version, verification and PASS / FAIL / DESTROY. If you can't verify the wipe, don't sell the storage."],
  ["Grade", "Test and grade", "Run bounded tests: memory, storage health, display, ports, battery, wireless, thermals. Record actual output. Deployment-ready means more than 'powers on'."],
  ["Reuse", "Reuse as-is where possible", "Whole-device value is the business. A working business laptop can be worth hundreds of dollars and becomes scrap metal, glass and PCB feedstock once it enters a recycling cage."],
  ["Repair", "Repair or refurbish where it pays", "Stop at a time, parts and safety ceiling. Measure gross margin per labour hour, not headline sale price."],
  ["Route", "Redeploy, resell or donate", "Commercial resale funds the operation. Lower-value but useful devices can go to trusted community partners for social reuse."],
  ["Parts", "Harvest parts if whole-device reuse fails", "RAM, SSDs, chargers and screens feed other repairs. Record what is left."],
  ["Recycle", "Recycle only the genuine remainder", "Send end-of-life material to a verified route (NTCRS scheme, MobileMuster, a named recycler) and keep the weight ticket or certificate."],
];

C.streams = [
  ["Commercial reuse", "Business, school or MSP retires devices → collect and inventory → ownership transfer → sanitise → test and grade → refurbish → resale or redeploy → client outcome report."],
  ["Social reuse", "Useful device with lower commercial value → sanitise, test, configure → trusted local charity or community partner → partner picks the recipient → skills and connectivity support where available."],
  ["Donor parts", "Whole device fails economic repair → harvest useful components → repair other equipment → record the remaining material."],
  ["End of life", "No meaningful whole or parts value → verified recycler or product-stewardship route → keep the weight ticket, certificate or receipt."],
];

C.takeaways = [
  ["Reuse before recycling is the opportunity", "Council, Officeworks, AMR and the regional NTCRS routes already handle disposal. The gap is earlier: identify the useful device, protect the data, refurbish, recover the whole-device value, and recycle last. Sircel, PonyUp, Reconnect, Compnow, WorkVentures and the National Device Bank all point the same way.", "SIRCEL-ITAD-REUSE-MODEL"],
  ["Triage is the highest-value operation", "The most valuable decision is 'is this actually end-of-life?' before anything goes into an e-waste cage. TechCollect says equipment surrendered into its stream is recycled in Australia and not sold second-hand.", "TECHCOLLECT-REUSE-DEEP-DIVE"],
  ["Corporate fleets beat random household e-waste", "Fleet-refresh gear is easier to identify, wipe, test, repair, image and sell. Target businesses, schools, professional offices, MSPs and community organisations. Keep household intake selective.", "GOOD360-COMPNOW-NATIONAL-DEVICE-BANK-DUBBO"],
  ["Data security is a differentiator", "Business clients want chain of custody, serials, sanitisation, verification, failed-erase escalation and a final outcome. Use the wording 'documented secure data erasure' until a certified process supports stronger claims.", "BACKLOG-21-25-COMPLIANCE-DATA-SAFETY"],
  ["Commercial resale and social reuse support each other", "Higher-value stock can be resold to pay for wiping, repairs, chargers and logistics, which then funds lower-value social devices. Run four streams: commercial, social, parts, recycling.", "GOOD360-COMPNOW-NATIONAL-DEVICE-BANK-DUBBO"],
  ["'We take e-waste' isn't a value proposition in Dubbo", "Dubbo already has Council drop-off, Officeworks, AMR, repairers and NetWaste routes. A stronger pitch: before you recycle old IT, we work out what still has value, protect the data, reuse what's viable and document what happened to the rest.", "BACKLOG-17-20-MARKET-COST-TAX"],
  ["Planning classification is the biggest barrier, not EPA tonnage", "A 20–30 device pilot is nowhere near EPA licensing thresholds, but being under a threshold doesn't create planning permission. Is it a home business, home industry, goods repair and reuse premises, or a waste activity? Council has to answer in writing.", "BACKLOG-01-05-PLANNING-LEGAL"],
  ["Launch tiny, selective and reversible", "Tuesday and Saturday by appointment, no public dumping, only items with a known exit, no loose lithium or CRTs, shelf limits, online sales. Copy Bendigo E-Waste's growth sequence, not its current warehouse.", "PHASE-0-OPERATING-BLUEPRINT"],
  ["The downstream chain is still opaque", "No public evidence proves where AMR Dubbo sends e-waste next. Sircel, ACE, Sims and TechCollect are candidates only. It stays 'unknown' until a written answer, transport document or certificate closes it.", "AMR-DUBBO-DOWNSTREAM-FORENSIC"],
  ["Pilot data now matters more than more research", "The real unknowns are empirical: local supply, reuse rate, repair time, sale price, days to sale, liability rate, recycling cost, gross margin per labour hour. The pilot tracker answers them.", "pilot-tracker.csv"],
];

C.gates = [
  ["Council classification", "Get Dubbo Regional Council's written answer on how the exact activity is classified on the proposed site."],
  ["Lease and workspace suitability", "Planning and lease permission are separate gates. The shed must be demonstrably dry and secure before it holds stock or unwiped drives."],
  ["Fair Trading answer", "Does the second-hand dealer regime apply, or the recycling-program exemption? Can you wipe during a 14-day hold? Get it in writing."],
  ["Insurance", "Public and product liability for a home electronics refurb, including lithium conditions. Quote required. Don't guess the premium."],
  ["Verified downstream terms", "A named, written route for the non-reusable remainder, with certificates or weight tickets."],
  ["Small selective pilot", "Pre-approved Tuesday/Saturday intake, shelf limits, online sales."],
  ["Measure 20–30 devices", "Log every item in the pilot tracker: labour, parts, days in stock, sale price, outcome."],
  ["Only then widen intake or spend", "Lease bigger space only when supply is consistent, stock turns, labour pays and storage is the real constraint."],
];

C.unknowns = [
  ["Can the home-site Phase 0 model run lawfully and safely?", "Council classification, site planning confirmation, landlord position, a dry and secure workspace, insurer acceptance. This is the main go/no-go gate."],
  ["Does the NSW second-hand dealer regime apply?", "The recycling-program exemption, donated or free equipment, the 14-day hold, whether wiping or repair counts as alteration."],
  ["Where does the non-reusable material physically go?", "AMR Dubbo, Council's post-June-2025 contractor, embedded lithium, NTCRS, AS 5377, CRTs, certificates, drive destruction."],
  ["Is there enough profitable good equipment in Dubbo?", "Only the pilot can answer: supply quality, reuse rate, repair success, labour, margins, shelf time, returns."],
  ["Which organisations will actually partner?", "Dubbo Support Center, Good Things, WorkVentures, Good360, the Device Banks, ANZRP, councils, local MSPs. Who says yes, in what role, at what volume?"],
];

